import { defineComponent, h, ref } from "vue";
import { useDraggable } from "@techui/libs/dnd-kit/vue/index.js";

const placement = ref(null);

const DraggableField = defineComponent({
  name: "DemoDroppablePlacementDraggableField",
  setup() {
    const element = ref(null);
    useDraggable({
      id: "field-block",
      element,
      type: "application/x-techui-placement",
      data: { id: "field-block", label: "Field Block" },
    });
    return () => h("div", { ref: element, class: "demo-placement-card" }, "Field Block");
  },
});

const handlePlacementChange = (detail) => {
  placement.value = detail.placement;
};
