import $c from "@techui/colors";
import { onMounted, reactive } from "vue";

const contentSize = { width: 500, height: 250 };

const randomSeries = (min, max, length, group) =>
  Array.from({ length: group }, () =>
    Array.from({ length }, () => Math.floor(Math.random() * (max - min + 1)) + min)
  );

const state = reactive({
  chartData: {
    legend: ["Data1", "Data2", "Data3"],
    xAxis: ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
    colors: [$c.cya4, $c.caa5, $c.aza6],
    data: [
      [100, 200, 400, 500, 400, 200, 100, 100, 200, 400, 200, 100],
      [100, 200, 300, 400, 300, 200, 50, 50, 100, 200, 100, 50],
      [200, 300, 400, 300, 200, 50, 50, 100, 100, 100, 50, 50],
    ],
  },
  chartOption: {},
  ready: false,
});

const createSeries = () => {
  const { legend, colors, data } = state.chartData;

  return legend.map((name, index) => ({
    name,
    type: "bar",
    label: {
      show: false,
      position: "insideRight",
    },
    itemStyle: {
      color: $c.fade(colors[index], 1),
      borderRadius: 5,
    },
    emphasis: {
      focus: "series",
    },
    data: data[index],
  }));
};

const processData = () => {
  const { legend, xAxis } = state.chartData;

  state.chartData.data = randomSeries(50, 200, 12, 3);
  state.chartOption.legend.data = legend;
  state.chartOption.xAxis.data = xAxis;
  state.chartOption.series = createSeries();
  state.ready = true;
};

const processOption = () => {
  state.ready = false;
  state.chartOption = {
    update: false,
    title: {
      show: false,
      text: "",
      textStyle: {
        color: $c.caa5,
        fontSize: 16,
        fontWeight: "normal",
      },
    },
    tooltip: {
      trigger: "axis",
      axisPointer: {
        type: "shadow",
      },
    },
    legend: {
      icon: "rect",
      data: [],
      right: "1%",
      top: 10,
    },
    toolbox: {
      show: false,
      feature: {
        magicType: {
          type: ["line", "bar"],
        },
      },
    },
    grid: {
      left: "3%",
      right: "3%",
      bottom: "8%",
      top: 40,
      containLabel: true,
    },
    yAxis: {
      type: "value",
      axisLabel: {
        align: "right",
      },
    },
    xAxis: {
      type: "category",
      data: [],
      splitLine: {
        show: false,
      },
      axisLabel: {
        align: "center",
      },
    },
    series: [],
  };

  processData();
};

